# model-common: what several model recipes share.
# Read by exportit/tools/export.py; described in exportit/MAP.md.
#
# The shared module files and the notes that belong to no single model
# (stage 5, the operator's answer to the follow-up on shared files).

covers models/
copy models/modulefiles/          modulefiles/
copy models/utils/                utils/
copy models/TODO                  TODO
copy models/compilation.notes     compilation.notes
copy models/mpiopts.note          mpiopts.note

# Files that exist only in the unit.
new UNIT.md        # what this unit is, where it came from, how it is checked
new LICENSE      # a copy of the repository's LICENSE
new Justfile
new tests/
new .gitignore   # the unit's own, since it is a repository of its own (MOVINGDAY.md)
